<?php $title='In Transit';$subtitle='Dispatched transfers whose goods have left the source warehouse and are not yet received (D-15).';$toolbar='<a class="button" href="/inventory-operations?kind=Transfer">All Transfers</a><a class="button" href="/inventory-operations">Stock Operations</a>';require __DIR__.'/start.php'; ?>
<p class="field-hint">In-transit units count in no warehouse: not at the source (already dispatched) and not available at the destination until it receives them. Replenishment treats them as inbound supply for the destination.</p>
<section class="table-scroll" aria-label="Transfers in transit"><table class="data-table"><thead><tr><th>Transfer</th><th>From</th><th>To</th><th>Lines</th><th>Units in transit</th><th>Dispatched</th><th>Days in transit</th><th>Action</th></tr></thead><tbody>
<?php foreach($result->items() as $row): ?><tr><td><a href="/inventory-operations/show?id=<?= (int)$row['id'] ?>">Transfer #<?= (int)$row['id'] ?></a> <span class="status-badge status-in-transit">In transit</span></td><td><?= $escape($row['warehouse_name']) ?></td><td><?= $escape($row['destination_name']) ?></td><td><?= (int)$row['line_count'] ?></td><td><?= (int)$row['units'] ?></td><td><?= $escape((string)$row['dispatched_at'].(($row['dispatcher_name']??null)!==null?' by '.$row['dispatcher_name']:'')) ?></td><td><?= (int)$row['age_days'] ?></td><td><a class="button" href="/inventory-operations/show?id=<?= (int)$row['id'] ?>">Receive</a></td></tr><?php endforeach; ?>
<?php if($result->total()===0): ?><tr><td colspan="8">No goods are in transit.</td></tr><?php endif; ?>
</tbody></table></section>
